// Gatilho de follow-up: sem mensagem nova do paciente — a Ana redige o toque da cadência.
// CORREÇÃO: a função ana_claim_followups() JÁ incrementou followup_step antes de devolver.
// Somar 1 aqui contava o passo em dobro — o paciente pulava o D+1 e recebia o xeque-mate
// do D+14 como segunda mensagem.
const lead = $('Um Lead por Vez').first().json;
const hist = $('Carregar Histórico FU').all().map(i => i.json);
const sys  = $('Carregar System Prompt FU').first().json.valor;
const step = Number(lead.followup_step) || 1;
const rotulos = {
  1: 'follow_up:D+1 — retome com uma dúvida leve e acolhedora (ex.: se ficou alguma dúvida no orçamento). NÃO cobre decisão.',
  2: 'follow_up:D+3 — traga um MOTIVO NOVO (oferecer verificar um horário da preferência dele, condição de pacote se já citada no histórico, facilidade do processo).',
  3: 'follow_up:D+7 — prova social leve e verdadeira + uma pergunta direta e gentil.',
  4: 'follow_up:D+14 — XEQUE-MATE ACOLHEDOR conforme o system prompt: facilite o não com elegância ("seu não também me ajuda").',
  5: 'follow_up:D+30 — último toque: gancho de calendário/rotina de saúde, porta aberta, sem pressão. Depois deste, a cadência encerra.',
};
const agora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', weekday: 'long', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const ctx = [
  '[CONTEXTO DA AUTOMAÇÃO — o paciente NÃO vê este bloco]',
  'Data/hora: ' + agora + ' (America/Sao_Paulo)',
  'Evento AUTOMÁTICO (o paciente NÃO enviou mensagem nova): ' + (rotulos[step] || 'follow_up'),
  'Nome: ' + (lead.nome || 'não informado') + ' · Exames em conversa: ' + JSON.stringify(lead.exames || []) + ' · Resumo interno: ' + (lead.resumo_interno || '-'),
  'Redija SOMENTE a mensagem deste passo, seguindo o bloco <follow_up> do seu prompt: curta (1 a 3 linhas), tom de quem se importa de verdade com a saúde do paciente, motivo novo, UMA pergunta, ZERO cobrança ("e aí, já decidiu?" é proibido). Não repita mensagens anteriores.',
  'Não cite valores que não estejam no histórico. NUNCA afirme que um horário está livre — ofereça verificar.',
  'Finalize com o bloco ###DADOS### em linha única.',
].join('\n');
const msgs = [];
for (const h of hist) {
  const role = h.role === 'assistant' ? 'assistant' : 'user';
  const c = String(h.conteudo || '').trim();
  if (!c) continue;
  if (msgs.length && msgs[msgs.length - 1].role === role) msgs[msgs.length - 1].content += '\n\n' + c;
  else msgs.push({ role, content: c });
}
while (msgs.length && msgs[0].role !== 'user') msgs.shift();
if (msgs.length && msgs[msgs.length - 1].role === 'user') msgs[msgs.length - 1].content += '\n\n' + ctx;
else msgs.push({ role: 'user', content: ctx });

// system como lista + cache_control: a partir da 2a chamada dentro da janela,
// a leitura do prompt custa uma fração do preço cheio.
const body = {
  model: $env.ANTHROPIC_MODEL || 'claude-sonnet-4-5',
  max_tokens: 700,
  system: [{ type: 'text', text: sys, cache_control: { type: 'ephemeral' } }],
  messages: msgs,
};
return [{ json: { anthropic_body: body, phone: lead.phone, step } }];

const resp = $json;
const base = $('Montar Payload FU').first().json;
const phone = base.phone, step = base.step;
let texto = '';
try { texto = (resp.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n').trim(); } catch (e) {}
let dados = { temperatura: 'morno', funil: 'fundo', consciencia: null, intencao: 'orcamento', exames_mencionados: [], convenio: null, agendamento: { status: 'nenhum', data: null, turno: null }, opt_out: false, proxima_acao: 'aguardar_resposta', escalar: false, motivo_escalada: null, resumo_interno: '' };
let msg = texto;
const ix = texto.indexOf('###DADOS###');
if (ix >= 0) {
  msg = texto.slice(0, ix).trim();
  const m = texto.slice(ix).match(/\{[\s\S]*\}/);
  if (m) { try { dados = Object.assign(dados, JSON.parse(m[0])); } catch (e) {} }
}
if (!msg) return [{ json: { skip: true, phone } }]; // falha da IA: devolve o passo e retenta
// Espaçamento da cadência: D+1 → D+3 → D+7 → D+14 → D+30 → encerra
const gaps = { 1: 2, 2: 4, 3: 7, 4: 16, 5: null };
let due = gaps[step] ? new Date(Date.now() + gaps[step] * 86400000).toISOString() : null;
if (dados.opt_out || dados.escalar || ['agendado', 'encerrar'].includes(dados.proxima_acao)) due = null;
return [{ json: {
  phone, mensagem: msg, step,
  pg_msg: JSON.stringify({ phone, conteudo: msg, dados }),
  pg_lead: JSON.stringify({ phone, step, followup_due: due, temperatura: dados.temperatura, proxima_acao: dados.proxima_acao, opt_out: !!dados.opt_out, escalado: !!dados.escalar, motivo_escalada: dados.motivo_escalada, resumo_interno: dados.resumo_interno || '' }),
} }];
